def compute(vars):
    bookings_2017 = vars["v1"]
    bookings_2018 = vars["v2"]
    average_bookings = (bookings_2017 + bookings_2018) / 2

    return {
        "value": average_bookings,
        "trace": {
            "bookings_2017": bookings_2017,
            "bookings_2018": bookings_2018,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
